  'extensive_network_desc' => 'गोरखपुर, लखनऊ, वाराणसी और अधिक में प्रॉपर्टी।',
  'facebook_login' => 'Facebook',
  'faq_a1' => 'APS Dream Home 8 से अधिक वर्षों से गोरखपुर और आसपास के क्षेत्रों में उपयोगकर्ताओं की सेवा कर रहा है। हमने रियल एस्टेट में एक विश्वसनीय नाम के रूप में खुद को स्थापित किया है।',
  'faq_a10' => 'हाँ, हम किरायेदार स्क्रीनिंग, किराया संग्रह, रखरखाव समन्वय और प्रॉपर्टी निरीक्षण सहित व्यापक प्रॉपर्टी प्रबंधन सेवाएँ प्रदान करते हैं।',
  'faq_a11' => 'बिल्कुल! हम प्रॉपर्टी पंजीकरण, दस्तावेज़ीकरण, स्टाम्प ड्यूटी भुगतान सहित एंड-टू-एंड कानूनी सहायता प्रदान करते हैं।',
  'faq_a12' => 'हाँ, हमने अनुभवी इंटीरियर डिज़ाइनरों के साथ साझेदारी की है जो आपकी नई प्रॉपर्टी को आपके सपनों का घर बनाने में मदद कर सकते हैं।',
  'faq_a13' => 'हम प्रॉपर्टी हैंडओवर सहायता, दोष सुधार (वारंटी अवधि के भीतर), रखरखाव मार्गदर्शन सहित व्यापक बिक्री के बाद सहायता प्रदान करते हैं।',
  'faq_a14' => 'हाँ, हम अपने सभी निर्माण प्रोजेक्ट्स पर संरचनात्मक वारंटी प्रदान करते हैं। वारंटी अवधि प्रोजेक्ट के प्रकार के अनुसार भिन्न होती है।',
  'faq_a15' => 'आप कई चैनलों के माध्यम से हमारी ग्राहक सहायता टीम से संपर्क कर सकते हैं:',
  'faq_a15_email' => 'ईमेल: support@apsdreamhome.com',
  'faq_a15_hours' => 'हमारी सहायता टीम सोमवार से शनिवार, सुबह 9:00 से शाम 7:00 बजे तक उपलब्ध है।',
  'faq_a15_office' => 'गोरखपुर में हमारे कार्यालय में आएँ',
  'faq_a15_phone' => 'फ़ोन: +91-7007444842',
  'faq_a15_web' => 'हमारी वेबसाइट संपर्क फ़ॉर्म के माध्यम से',
  'faq_a2' => 'हम मुख्य रूप से गोरखपुर और उत्तर प्रदेश के आसपास के क्षेत्रों में सेवा देते हैं। हमारे लखनऊ, वाराणसी और प्रयागराज में भी प्रोजेक्ट हैं।',
  'faq_a3' => 'हाँ, APS Dream Home एक पूरी तरह से लाइसेंस प्राप्त और पंजीकृत रियल एस्टेट कंपनी है। हम सभी स्थानीय नियमों का पालन करते हैं।',
  'faq_a4' => 'हम आवासीय अपार्टमेंट, स्वतंत्र मकान, विला, वाणिज्यिक स्थान और प्लॉट सहित कई प्रकार की प्रॉपर्टी प्रदान करते हैं।',
  'faq_a5' => 'हमारी सभी प्रॉपर्टी पूरी कानूनी जाँच से गुज़रती हैं। हम टाइटल डीड, स्वीकृत बिल्डिंग प्लान, अधिभोग प्रमाण पत्र सहित पूरा दस्तावेज़ीकरण प्रदान करते हैं।',
  'faq_a6' => 'बिल्कुल! हम अपनी सभी प्रॉपर्टी के लिए साइट विज़िट को प्रोत्साहित करते हैं। हमारी सेल्स टीम सुविधाजनक समय पर विज़िट की व्यवस्था कर सकती है।',
  'faq_a7' => 'प्रॉपर्टी कीमतों में आमतौर पर प्रॉपर्टी की आधार लागत, पंजीकरण शुल्क और बुनियादी सुविधाएँ शामिल हैं। स्टाम्प ड्यूटी, कानूनी शुल्क अलग हैं।',
  'faq_a8' => 'हाँ, हमारी प्रमुख बैंकों और वित्तीय संस्थानों के साथ टाई-अप है। हमारी टीम होम लोन आवेदन, दस्तावेज़ीकरण में आपकी सहायता कर सकती है।',
  'faq_a9' => 'हाँ, प्रॉपर्टी आरक्षित करने के लिए आमतौर पर एक रिफंडेबल बुकिंग राशि आवश्यक होती है। यह राशि प्रॉपर्टी मूल्य के अनुसार भिन्न होती है।',
  'faq_q1' => 'APS Dream Home कितने समय से व्यवसाय में है?',
  'faq_q10' => 'क्या आप प्रॉपर्टी प्रबंधन सेवाएँ प्रदान करते हैं?',
  'faq_q11' => 'क्या आप प्रॉपर्टी पंजीकरण और कानूनी कार्यवाही में मदद कर सकते हैं?',
  'faq_q12' => 'क्या आप इंटीरियर डिज़ाइन सेवाएँ प्रदान करते हैं?',
  'faq_q13' => 'आप किस प्रकार की बिक्री के बाद सहायता प्रदान करते हैं?',
  'faq_q14' => 'क्या निर्माण गुणवत्ता पर वारंटी है?',
  'faq_q15' => 'मैं ग्राहक सहायता से कैसे संपर्क कर सकता हूँ?',
  'faq_q2' => 'आप किन क्षेत्रों में सेवा देते हैं?',
  'faq_q3' => 'क्या आप लाइसेंस प्राप्त और पंजीकृत हैं?',
  'faq_q4' => 'आप किस प्रकार की प्रॉपर्टी प्रदान करते हैं?',
  'faq_q5' => 'मुझे कैसे पता चलेगा कि प्रॉपर्टी कानूनी रूप से स्पष्ट है?',
  'faq_q6' => 'क्या मैं खरीदने से पहले प्रॉपर्टी देख सकता हूँ?',
  'faq_q7' => 'प्रॉपर्टी कीमत में क्या शामिल है?',
  'faq_q8' => 'क्या आप होम लोन या फाइनेंसिंग विकल्प प्रदान करते हैं?',
  'faq_q9' => 'क्या बुकिंग राशि आवश्यक है?',
  'faq_title' => 'अक्सर पूछे जाने वाले प्रश्न',
  'faqs' => 'सामान्य प्रश्न',
  'faqs_a1' => 'APS Dream Home 8 से अधिक वर्षों से गोरखपुर और आसपास के क्षेत्रों में उपयोगकर्ताओं की सेवा कर रहा है। हमने सफल परियोजनाओं और संतुष्ट उपयोगकर्ताओं के सिद्ध ट्रैक रिकॉर्ड के साथ रियल एस्टेट में एक विश्वसनीय नाम के रूप में खुद को स्थापित किया है।',
  'faqs_a10' => 'हाँ, हम किरायेदार स्क्रीनिंग, किराया संग्रह, रखरखाव समन्वय और संपत्ति निरीक्षण सहित व्यापक संपत्ति प्रबंधन सेवाएँ प्रदान करते हैं। हमारी संपत्ति प्रबंधन टीम सुनिश्चित करती है कि आपका निवेश अच्छी तरह से रखरखाव और लाभदायक है।',
  'faqs_a11' => 'बिल्कुल! हम संपत्ति पंजीकरण, दस्तावेज़ीकरण, स्टांप ड्यूटी भुगतान और सरकारी अधिकारियों के साथ संपर्क सहित अंत-से-अंत कानूनी सहायता प्रदान करते हैं। हमारी कानूनी टीम सुनिश्चित करती है कि सभी कागजी कार्रवाई सटीक और कुशलता से पूरी हो।',
  'faqs_a12' => 'हाँ, हमने अनुभवी इंटीरियर डिज़ाइनरों के साथ साझेदारी की है जो आपकी नई संपत्ति को आपके सपनों के घर में बदलने में मदद कर सकते हैं। हम विभिन्न बजट और प्राथमिकताओं के अनुकूल अनुकूलित इंटीरियर डिज़ाइन पैकेज प्रदान करते हैं।',
  'faqs_a13' => 'हम संपत्ति सौंपने में सहायता, दोष सुधार (वारंटी अवधि के भीतर), रखरखाव मार्गदर्शन और निरंतर ग्राहक सहायता सहित व्यापक बिक्री के बाद सहायता प्रदान करते हैं। उपयोगकर्ताओं के साथ हमारा संबंध बिक्री पूरी होने के बाद भी लंबे समय तक जारी रहता है।',
  'faqs_a14' => 'हाँ, हम अपनी सभी निर्माण परियोजनाओं पर संरचनात्मक वारंटी प्रदान करते हैं। वारंटी अवधि परियोजना के प्रकार के अनुसार भिन्न होती है और आपके बिक्री समझौते में निर्दिष्ट की जाएगी। हम अतिरिक्त मन की शांति के लिए विस्तारित वारंटी विकल्प भी प्रदान करते हैं।',
  'faqs_a15' => 'आप कई चैनलों के माध्यम से हमारी ग्राहक सहायता टीम से संपर्क कर सकते हैं: फ़ोन: +91-7007444842, ईमेल: support@apsdreamhome.com, गोरखपुर में हमारे कार्यालय पर जाएँ, हमारी वेबसाइट संपर्क फ़ॉर्म के माध्यम से। हमारी सहायता टीम सोमवार से शनिवार, सुबह 9:00 से शाम 7:00 बजे तक उपलब्ध है।',
  'faqs_a2' => 'हम मुख्य रूप से उत्तर प्रदेश के गोरखपुर और आसपास के क्षेत्रों में सेवा प्रदान करते हैं। हमारे लखनऊ, वाराणसी और इलाहाबाद में भी परियोजनाएँ हैं। हमारी विशेषज्ञता इन क्षेत्रों में आवासीय, वाणिज्यिक और प्लॉट विकास को कवर करती है।',
  'faqs_a3' => 'हाँ, APS Dream Home पूरी तरह से लाइसेंस प्राप्त और पंजीकृत रियल एस्टेट कंपनी है। हम सभी स्थानीय नियमों का पालन करते हैं और अपनी सभी परियोजनाओं के लिए उचित दस्तावेज़ीकरण बनाए रखते हैं। हमारी पंजीकरण और लाइसेंसिंग जानकारी अनुरोध पर उपलब्ध है।',
  'faqs_a4' => 'हम आवासीय अपार्टमेंट, स्वतंत्र मकान, विला, वाणिज्यिक स्थान और प्लॉट सहित विभिन्न प्रकार की संपत्तियाँ प्रदान करते हैं। हमारे पोर्टफोलियो में रहने के लिए तैयार संपत्तियाँ और निर्माणाधीन परियोजनाएँ दोनों शामिल हैं।',
  'faqs_a5' => 'हमारी सभी संपत्तियाँ पूरी कानूनी जाँच से गुज़रती हैं। हम शीर्षक विलेख, अनुमोदित भवन योजनाएँ, अधिभोग प्रमाणपत्र और अन्य आवश्यक कानूनी मंजूरी सहित पूर्ण दस्तावेज़ीकरण प्रदान करते हैं। हमारी कानूनी टीम सुनिश्चित करती है कि हर संपत्ति सभी नियामक आवश्यकताओं को पूरा करती है।',
  'faqs_a6' => 'बिल्कुल! हम अपनी सभी संपत्तियों के लिए साइट विज़िट को प्रोत्साहित करते हैं। हमारी बिक्री टीम सुविधाजनक समय पर संपत्ति विज़िट की व्यवस्था कर सकती है। हम पूर्ण पारदर्शिता में विश्वास करते हैं और चाहते हैं कि आप देखें कि आप वास्तव में किसमें निवेश कर रहे हैं।',
  'faqs_a7' => 'संपत्ति की कीमतों में आमतौर पर संपत्ति की आधार लागत, पंजीकरण शुल्क और बुनियादी सुविधाएँ शामिल होती हैं। स्टांप ड्यूटी, कानूनी शुल्क और रखरखाव शुल्क (यदि लागू हो) जैसी अतिरिक्त लागतें अलग हैं और खरीद प्रक्रिया के दौरान स्पष्ट रूप से बताई जाएंगी।',
  'faqs_a8' => 'हाँ, हमारी प्रमुख बैंकों और वित्तीय संस्थानों के साथ साझेदारी है। हमारी टीम होम लोन आवेदन, दस्तावेज़ीकरण और सर्वोत्तम ब्याज दरें प्राप्त करने में आपकी सहायता कर सकती है। हम आपको पूरी वित्तपोषण प्रक्रिया में मार्गदर्शन करते हैं।',
  'faqs_a9' => 'हाँ, किसी संपत्ति को आरक्षित करने के लिए आमतौर पर एक वापसी योग्य बुकिंग राशि आवश्यक होती है। यह राशि संपत्ति के मूल्य के अनुसार भिन्न होती है और बिक्री पूरी होने पर कुल भुगतान के विरुद्ध समायोजित की जाएगी। यदि आप आगे नहीं बढ़ने का निर्णय लेते हैं तो सभी बुकिंग राशि पूरी तरह से वापसी योग्य हैं।',
